# %% ../nbs/05_transforms.ipynb #de985f9d
class RandGaussianSmooth(RandMonaiTransform):
    """
    Apply Gaussian smoothing with randomly sampled sigma.
    """

    def __init__(self,
                 sigma_x=(0.5,1.5),
                 sigma_y=None,
                 sigma_z=None,
                 prob=0.1,
                 approx="erf",
                 has_channels=True):

        def sample_sigma(r):
            if r is None:
                return None
            if np.iterable(r):
                return np.random.uniform(r[0], r[1])
            return r

        def param_sampler():
            sigma = tuple(filter(None, [
                sample_sigma(sigma_x),
                sample_sigma(sigma_y),
                sample_sigma(sigma_z)
            ]))

            return dict(sigma=sigma)

        super().__init__(
            tfms.GaussianSmooth,
            prob=prob,
            param_sampler=param_sampler,
            has_channels=has_channels,
            approx=approx
        )

